// Stem + consonantal suffix. ن and ت merge with an identical stem-final letter (كنّا → كنا، سكنّ → سكن، سكتّ → سكت).
const join = (stem, suf) => (suf && 'نت'.includes(suf[0]) && stem.endsWith(suf[0]) ? stem + suf.slice(1) : stem + suf);
