const imperativeSimple = core => ({ ms: [core], fs: [core + 'ي'], d: [core + 'ا'], mp: [core + 'وا'], fp: [join(core, 'ن')] });
const imperativeHollow = (long, short) => ({ ms: [short], fs: [long + 'ي'], d: [long + 'ا'], mp: [long + 'وا'], fp: [join(short, 'ن')] });
